!solve(input){
stack = input.stack;
action = input.action;
value = input.value;
history = input.history;

?(action == "push"){
newStack = [...stack, value];
newHistory = [...history, {type: "push", value: value}];
}:(action == "pop"){
?(stack.length > 0){
newStack = stack.slice(0, -1);
newHistory = [...history, {type: "pop", value: stack[stack.length - 1]}];
}:(stack.length == 0){
newStack = stack;
newHistory = history;
}
}:(action == "rollback"){
?(history.length > 0){
lastAction = history[history.length - 1];
?(lastAction.type == "push"){
newStack = stack.slice(0, -1);
newHistory = history.slice(0, -1);
}:(lastAction.type == "pop"){
newStack = [...stack, lastAction.value];
newHistory = history.slice(0, -1);
}
}:(history.length == 0){
newStack = stack;
newHistory = history;
}
}^{
stack: newStack,
history: newHistory
}
}

!solve(input){
  buffer = input.buffer;
  item = input.item;
  if (buffer.length < 3) {
    buffer.push(item);
  } else {
    buffer.shift();
    buffer.push(item);
  }
  ^buffer
}
